[SPECIALIST_FINDING]
{
  "specialty": "kdoctor-nephrology",
  "answer": "3개월간 eGFR 58→41로 빠른 악화(연간 -17 소실, 즉 >5 mL/min/1.73m²/yr 초과)에 요단백 +++가 동반된 67세 당뇨 환자로, 만성 당뇨병 콩팥병증(DKD)의 자연 경과만으로 설명하기 어려운 '비당뇨성 급성 악화 요인'이 겹쳤을 가능성이 높습니다. 즉시 배제해야 할 것은 ① 허혈성 신병증(신혈관 폐색·양측 신동맥 협착/폐색), ② 급성 간질성 신염(AIN, 약물 유발 포함), ③ 약물 유발 신손상(NSAIDs·조영제·항생제·PPI 등), ④ 급속 진행성 사구체신염(RPGN) 및 비당뇨성 사구체 질환, ⑤ 신후성 폐색입니다. 다만 이는 소변·혈액 검사와 영상 없이는 확정할 수 없고, 아래 검사로 좁혀야 합니다.",
  "red_flag": {
    "present": false,
    "items": [
      { "id": "NE1", "evidence": "무뇨/핍뇨 여부, 부종·호흡곤란 여부가 질문에 명시되지 않음 — 미확인", "basis": "history" },
      { "id": "NE3", "evidence": "혈압 수치·두통·시야 이상 미제공 — 미확인", "basis": "history" },
      { "id": "NE5", "evidence": "발열·옆구리 통증·배뇨통 미제공 — 미확인", "basis": "history" },
      { "id": "NE6", "evidence": "요독 증상(구토·가려움·혼돈·심막통 호흡) 미제공 — 미확인", "basis": "history" }
    ]
  },
  "hypotheses": [
    {
      "name": "비당뇨성 급성/아급성 악화 (RPGN, AIN, 허혈성 신병증, 약물 유발 AKI, 신후성 폐색 등)",
      "icd10": "N00–N29 / N17 / N18 혼재",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "3개월간 eGFR 58→41, 연간 소실로 환산 시 약 -17 mL/min/1.73m²/yr로 DKD 자연 경과(통상 연 -2~-5)보다 빠름", "basis": "measurement" },
        { "text": "요단백 +++(중등도 이상 단백뇨)", "basis": "measurement" },
        { "text": "당뇨 환자에서 RAS 차단제·SGLT2i·NSAIDs·조영제 등 신기능 영향 약제 노출 가능성", "basis": "history" }
      ],
      "against": [
        { "text": "DKD 자체도 장기 경과 중 급성 악화(급성 악화 on CKD)를 보일 수 있어 비당뇨성 원인이 반드시 필요하지는 않음", "basis": "guideline" },
        { "text": "요단백 +++는 DKD 소견과 일치 — 단백뇨 자체만으로 비당뇨성 사구체 질환을 시사하지 않음", "basis": "guideline" }
      ]
    },
    {
      "name": "급속 진행성 사구체신염 / 비당뇨성 사구체 질환(ANCA, 항GBM, 면역복합체 등)",
      "icd10": "N01",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
