      ],
      "against": [
        { "text": "혈압 저하·저관류 소견, 폐부종·난치성 고혈압, 최근 조영제/혈관 시술 여부 미제공", "basis": "history" }
      ]
    },
    {
      "name": "약물 유발 신손상(NSAIDs, 조영제, 항생제, PPI, RAS차단제+SGLT2i 병용 등)",
      "icd10": "N14 / N17",
      "must_not_miss": true,
      "probability_band": "medium",
      "supports": [
        { "text": "당뇨 환자에서 위 약제 병용이 흔함", "basis": "guideline" }
      ],
      "against": [
        { "text": "구체적 약물 목록·노출 시점 미제공", "basis": "history" }
      ]
    },
    {
      "name": "신후성(폐색성) 신병증 — 전립선·결석·종양",
      "icd10": "N13 / N40",
      "must_not_miss": true,
      "probability_band": "low",
      "supports": [
        { "text": "67세 남성이면 전립선 폐색 가능성 존재", "basis": "history" }
      ],
      "against": [
        { "text": "배뇨 증상·요저류·옆구리 통증·영상 미제공", "basis": "history" }
      ]
    },
    {
      "name": "당뇨병 콩팥병증(DKD) 단독 진행",
      "icd10": "E11.2 / N18",
      "must_not_miss": false,
      "probability_band": "medium",
      "supports": [
        { "text": "당뇨 + 요단백 +++ + eGFR 감소", "basis": "guideline" }
      ],
      "against": [
        { "text": "3개월 -17은 DKD 자연 경과로는 빠름 — 단독 설명 어려움", "basis": "guideline" }
      ]
    }
  ],
  "missing_info": [
